-- Города «Работы России»: убираем «Город » в начале и возвращаем регионам полное название,
-- чтобы посадочные страницы по городам не показывали «Город Москва» и «Свердловская»
UPDATE "Vacancy" SET "city" = regexp_replace("city", '^\s*(Город|город|г\.)\s+', '') WHERE "source" = 'TRUDVSEM' AND "city" ~ '^\s*(Город|город|г\.)\s+';
UPDATE "Vacancy" SET "city" = "city" || ' область' WHERE "source" = 'TRUDVSEM' AND "city" ~ '^[А-Яа-яЁё-]+(ая|яя)$' AND "city" NOT IN ('Москва', 'Санкт-Петербург', 'Севастополь');
UPDATE "Vacancy" SET "city" = "city" || ' край' WHERE "source" = 'TRUDVSEM' AND "city" IN ('Пермский', 'Красноярский', 'Краснодарский', 'Ставропольский', 'Алтайский', 'Хабаровский', 'Приморский', 'Забайкальский', 'Камчатский');
